window.products.push({"id":256633,"name":"Cleveland Skyline 2018 Photo Print UNFRAMED Night Color City Downtown 11.75 inches x 36 inches Ohio Photographic Panorama Poster Picture Standard Size","category":"homeandappliances","retail price":24.9,"sale price":null,"image":"https://m.media-amazon.com/images/I/614PBkeLisL._AC_SL1000_.jpg","description":"【FRAME NOT INCLUDED】BUT this size print EXACTLY fits an easy-to-find frame found at most any hobby store. See Video for more info. 【OPTIONS】Other versions, sizes, material. Use search bar in photosbyjon shop to see all items 【QUALITY IMAGE】Note the DETAIL in even the brightest & darkest areas, unlike some images on other low priced products 【BETTER THAN A POSTER】True Photo Quality, printed on durable photo paper that lasts DECADES (Posters start to fade after a few years) 【GENUINE USA】by Award-winning photographer Jon Holiday","images":["https://m.media-amazon.com/images/I/614PBkeLisL._AC_SL1000_.jpg","https://m.media-amazon.com/images/I/61zNIJh6ZCL._SL1500_.jpg","https://m.media-amazon.com/images/I/61TWUez1VxL._AC_SL1500_.jpg","https://m.media-amazon.com/images/I/51TIpnkrEpL._AC_SL1500_.jpg","https://m.media-amazon.com/images/I/51I6jTu8yCL._AC_SL1300_.jpg","https://m.media-amazon.com/images/I/31o9GyU6jnL._AC_.jpg"],"specifications":{"brand":"PHOTOSBYJON","source_asin":"B00F8HGSMY","category_path":"Home & Kitchen"},"sku":"BM-256633","productType":"Home & Appliances","inventory":0,"age_group":"Adult","gender":"Unisex","source_url":"https://www.amazon.com/dp/B00F8HGSMY","source_catalog":"Amazon Reviews 2023 product metadata","source_file":"meta_Home_and_Kitchen_2023.jsonl","source_asin":"B00F8HGSMY","price_pending":true,"merchant_ready":false});
